"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["20583"],{85250(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.peso_invalido","status":422,"titulo":"O peso da etapa, quando informado, deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.peso_invalido","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["Uma das etapas do corpo do pedido informou `peso` menor ou igual a zero. O campo \xe9\\nopcional \u2014 uma etapa sem peso \xe9 v\xe1lida \u2014, mas quando informado precisa ser\\npositivo: \xe9 o peso, junto do car\xe1ter classificat\xf3ria/ambas, que determina se a\\netapa entra na f\xf3rmula da nota final (`NOTA FINAL = Soma(Etapa \xd7 peso) /\\ndivisor`); um peso zero ou negativo n\xe3o tem interpreta\xe7\xe3o v\xe1lida nessa\\nf\xf3rmula.","Esta \xe9 uma das confer\xeancias de forma que a defini\xe7\xe3o de etapas acumula numa s\xf3\\npassada, antes de resolver qualquer etapa contra o cat\xe1logo de tipos. A lista\\ncompleta das confer\xeancias, o mecanismo de acumula\xe7\xe3o e a ordem em que as viola\xe7\xf5es\\naparecem est\xe3o em [`nome_obrigatorio`](/erros/uniplus.selecao.etapa_processo.nome_obrigatorio).","Sobre o `peso`, a passada faz duas confer\xeancias, e a segunda s\xf3 vale quando a\\nprimeira passa: peso menor ou igual a zero (este c\xf3digo) e peso informado em\\netapa apenas eliminat\xf3ria, que n\xe3o comp\xf5e a nota\\n(`uniplus.selecao.etapa_processo.peso_sem_carater_que_pontua`).","O valor \xe9 persistido como `numeric(18,4)` \u2014 um peso positivo com mais de 4\\ncasas decimais \xe9 recusado antes desta confer\xeancia, por valida\xe7\xe3o de corpo do pedido\\n(forma/rota, sem confer\xeancia de dom\xednio equivalente), para que o banco nunca\\narredonde silenciosamente um peso que o cliente pretendia diferente de zero."],"comoResolver":["Informe um `peso` positivo, ou omita o campo se a etapa n\xe3o deve compor a nota\\nfinal. Se a resposta trouxer mais de uma viola\xe7\xe3o no array `errors[]`,\\ncorrija todas antes de reenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);